const readline = require("readline-sync");

const {
    calcularMaoDeObra,
    calcularTotal,
    verificarDesconto
} = require("./funcoesOrcamento");

const cliente = readline.question("Nome do cliente: ");
const valorMateriais = readline.questionFloat("Valor dos materiais: ");
const horas = readline.questionFloat("Horas de servico: ");

const maoDeObra = calcularMaoDeObra(horas);
const total = calcularTotal(valorMateriais, horas);
const desconto = verificarDesconto(total);

console.log("\n===== RELATORIO DO ORCAMENTO =====");
console.log(`Cliente: ${cliente}`);
console.log(`Materiais: R$ ${valorMateriais.toFixed(2)}`);
console.log(`Mao de obra: R$ ${maoDeObra.toFixed(2)}`);
console.log(`Total: R$ ${total.toFixed(2)}`);
console.log(`Situacao do desconto: ${desconto}`);